def preprocess(s):
    n = len(s)
    lps = [0] * n
    j = 0
    for i in range(1, n):
        while (j > 0 and s[i] != s[j]):
            j = lps[j - 1]
        if s[i] == s[j]:
            j += 1
            lps[i] = j
    return lps

def kmp_search(s, pattern):
    lps = preprocess(pattern + "#" + s)
    count = 0
    for i in range(len(pattern), len(lps)):
        if lps[i] == len(pattern):
            count += 1
    return count

def cyclic_isomorphic_substrings(s, queries):
    results = []
    for x in queries:
        doubled_x = x + x
        results.append(kmp_search(s, doubled_x))
    return results

